function response(data, status = 200) {
  return new Response(JSON.stringify(data), { status, headers: { "content-type": "application/json" } });
}

function redactPrivateTranscript(value) {
  let text = String(value || ""); let count = 0;
  const patterns = [
    [/\b[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}\b/gi, "[EMAIL REDACTED]"],
    [/(?<!\d)(?:\+?1[-. (]*)?(?:\d{3}|\(\d{3}\))[-. )]*\d{3}[-. ]*\d{4}(?!\d)/g, "[PHONE REDACTED]"],
    [/\b\d{3}[- ]?\d{2}[- ]?\d{4}\b/g, "[SSN REDACTED]"],
    [/\b(?:sk|api|token|secret)[-_][A-Za-z0-9_-]{16,}\b/gi, "[CREDENTIAL REDACTED]"],
  ];
  for (const [pattern, replacement] of patterns) text = text.replace(pattern, () => { count += 1; return replacement; });
  return { text, count };
}

const dnaWeights = { marketCoverage: .25, messagingConsistency: .2, behaviorReadiness: .2, evidenceFreshness: .15, closedLoopActivation: .1, governanceHealth: .1 };

export function calculateRevenueDna(input) {
  const callCount = Math.max(0, Number(input.callCount || 0));
  if (!callCount) return { status: "insufficient_evidence", overall: null, confidence: 0, components: null };
  const clamp = (value) => Math.max(0, Math.min(100, Math.round(value)));
  const expectedNodes = callCount * 6; const expectedAssets = callCount * 20; const expectedReadiness = callCount * 3;
  const driftPenalty = (input.signals || []).filter((signal) => signal.signal_type === "knowledge_drift").reduce((sum, signal) => sum + (signal.severity === "high" ? 18 : signal.severity === "medium" ? 9 : 4), 0);
  const components = {
    marketCoverage: clamp((Number(input.nodeCount || 0) / expectedNodes) * 60 + Math.min(40, callCount * 8)),
    messagingConsistency: clamp(100 - driftPenalty),
    behaviorReadiness: clamp((Number(input.approvedReadinessAssetCount ?? input.readinessAssetCount ?? 0) / expectedReadiness) * 100),
    evidenceFreshness: clamp((Number(input.recentCallCount || 0) / callCount) * 100),
    closedLoopActivation: clamp((Number(input.approvedAssetCount || 0) / expectedAssets) * 100),
    governanceHealth: clamp((Number(input.consentedCallCount || 0) / callCount) * 100),
  };
  const overall = Math.round(Object.entries(dnaWeights).reduce((sum, [key, weight]) => sum + components[key] * weight, 0));
  return { status: "complete", overall, confidence: clamp(40 + callCount * 12), components, weights: dnaWeights };
}

function redact(text) {
  return text.replace(/[A-Z0-9._%+-]+@[A-Z0-9.-]+\.[A-Z]{2,}/gi, "[EMAIL]").replace(/(?:\+?1[-.\s]?)?\(?\d{3}\)?[-.\s]?\d{3}[-.\s]?\d{4}/g, "[PHONE]");
}

