export function validateAssetReview(input) {
  const decision = String(input?.decision || ""); const rationale = String(input?.rationale || "").trim().slice(0, 1000);
  if (!["approved", "changes_requested", "rejected"].includes(decision)) return { ok: false, code: "validation_failed" };
  if (decision !== "approved" && rationale.length < 8) return { ok: false, code: "rationale_required" };
  return { ok: true, decision, rationale: rationale || "Approved after evidence review." };
}

