document.querySelector('#security .security-grid').insertAdjacentHTML('afterend','<div class="governance-shell"><article class="panel danger-zone"><span class="eyebrow">Deletion control</span><h2>Queue a governed deletion</h2><p class="muted">Requests enter a 72-hour cooling-off window. Source calls, derived assets, graph evidence, retained files, and controlled copies are handled through lineage-aware deletion.</p><form id="deletionForm" class="governance-form"><label>Scope<select name="scope"><option value="call">Call</option><option value="user">User</option><option value="organization">Organization</option></select></label><label>Target ID<input name="targetId" required placeholder="Call, user, or organization ID"></label><button class="button dark" type="submit">Queue request</button></form><div class="queue-block"><h2>Deletion queue</h2><div id="deletionQueue" class="queue-list"></div></div></article><article class="panel"><span class="eyebrow">Append-only accountability</span><h2>Governance audit</h2><p class="muted">Asset decisions, connector checks, advisor commands, and deletion requests retain actor and timestamp without copying transcript content.</p><div id="auditList" class="audit-list"></div></article></div>');
