loadGovernance=async function(){const [deletions,audit]=await Promise.all([fetch('/api/revenue-os/deletions').then(r=>r.json()),fetch('/api/revenue-os/audit').then(r=>r.json())]);document.querySelector('#deletionQueue').innerHTML=deletions.length?deletions.map(d=>{const tasks=(d.tasks||[]).map(t=>clean(statusLabel(t.system_name))+': '+clean(statusLabel(t.status))).join(' · ');return '<div class="queue-row"><b>'+clean(statusLabel(d.scope))+' · '+clean(d.target_id)+'</b><span>'+clean(statusLabel(d.status))+' · executes after '+clean(formatDate(d.delete_after))+(tasks?'<br>'+tasks:'')+'</span>'+(d.status==='queued'?'<button class="button secondary compact" data-cancel-deletion="'+clean(d.id)+'">Cancel</button>':'')+'</div>'}).join(''):'<div class="empty">No deletion requests queued.</div>';document.querySelector('#auditList').innerHTML=audit.length?audit.slice(0,12).map(a=>'<div class="audit-row"><b>'+clean(statusLabel(a.action))+'</b><span>'+clean(a.actor)+' · '+clean(statusLabel(a.entity_type))+' · '+clean(formatDate(a.created_at))+'</span></div>').join(''):'<div class="empty">No governed actions recorded yet.</div>'};
document.body.addEventListener('click',async event=>{const button=event.target.closest('[data-cancel-deletion]');if(!button)return;if(!confirm('Cancel this deletion request?'))return;button.disabled=true;try{const result=await fetch('/api/revenue-os/deletions/'+encodeURIComponent(button.dataset.cancelDeletion),{method:'DELETE'}).then(async response=>{const body=await response.json();if(!response.ok)throw new Error(body.message||body.code);return body});toast('Deletion request cancelled');await loadGovernance()}catch(error){toast(error.message||'Request could not be cancelled')}finally{button.disabled=false}});
