async function loadPersonaGovernance(){const target=document.querySelector('#personaGovernanceBody');if(!target)return;target.innerHTML='<div class="empty">Loading persona lineage…</div>';const personas=await optionalJson('/api/revenue-os/personas');if(!Array.isArray(personas)||!personas.length){target.innerHTML='<div class="empty">No live persona draft yet. Ingest a consent-confirmed transcript to create one.</div>';return}const persona=personas[0];const detail=await optionalJson('/api/revenue-os/assets/'+encodeURIComponent(persona.id));const evidence=Array.isArray(detail?.evidence)?detail.evidence:[];target.className='';target.innerHTML='<div class="review-summary"><div><span class="tag '+statusTag(persona.status)+'">'+clean(statusLabel(persona.status))+'</span><span class="tag">'+clean(persona.consent_status)+'</span></div><b>'+clean(persona.title)+'</b><span>'+clean(persona.source_title)+' · '+evidence.length+' source-linked claims · v'+Number(persona.latest_version||0)+'</span></div><p class="soft-note"><b>Confidence model:</b> each claim retains its own source evidence. Version confidence improves with source diversity; inferred or unknown fields stay separate from observed facts.</p><div class="evidence-list">'+evidence.map((item,index)=>'<article class="evidence-card"><span class="confidence">'+Math.round(Number(item.confidence||0)*100)+'% · observed</span><b>'+clean(statusLabel(item.node_type))+' · '+clean(item.label)+'</b><span>“'+clean(item.evidence)+'”</span><div class="status-line"><button class="button secondary compact" data-persona-claim="'+clean(item.id)+'" data-persona-disposition="accepted">Accept</button><button class="button secondary compact" data-persona-claim="'+clean(item.id)+'" data-persona-disposition="rejected">Reject</button></div></article>').join('')+'</div><div class="status-line" style="margin-top:14px"><span id="personaReviewProgress" class="tag">0 of '+evidence.length+' reviewed</span><button class="button" id="publishPersonaVersion" disabled>Publish immutable version</button></div>';const reviews={};target.querySelectorAll('[data-persona-claim]').forEach(button=>button.onclick=()=>{reviews[button.dataset.personaClaim]=button.dataset.personaDisposition;target.querySelectorAll('[data-persona-claim="'+CSS.escape(button.dataset.personaClaim)+'"]').forEach(item=>item.classList.toggle('selected',item===button));document.querySelector('#personaReviewProgress').textContent=Object.keys(reviews).length+' of '+evidence.length+' reviewed';document.querySelector('#publishPersonaVersion').disabled=Object.keys(reviews).length!==evidence.length});document.querySelector('#publishPersonaVersion').onclick=async()=>{const button=document.querySelector('#publishPersonaVersion');button.disabled=true;try{const reviewResponse=await fetch('/api/revenue-os/personas/'+encodeURIComponent(persona.id)+'/claims',{method:'POST',headers:{'content-type':'application/json'},body:JSON.stringify({reviews:Object.entries(reviews).map(([claimId,disposition])=>({claimId,disposition}))})});if(!reviewResponse.ok)throw new Error((await reviewResponse.json()).message);const publishResponse=await fetch('/api/revenue-os/personas/'+encodeURIComponent(persona.id)+'/publish',{method:'POST'});const result=await publishResponse.json();if(!publishResponse.ok)throw new Error(result.message);toast('Persona version '+result.version+' published with immutable lineage');await loadPersonaGovernance()}catch(error){toast(error.message||'Persona could not be published')}finally{button.disabled=false}}}
